import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import type { DbHandle } from './client.js';

/** SQL migrations generated by drizzle-kit, shipped inside the package. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../drizzle', import.meta.url));

/** Arbitrary constant; every checkout-sentinel process uses the same one. */
const MIGRATION_LOCK_KEY = 7_204_311;

/**
 * Applies pending migrations. A Postgres advisory lock serializes concurrent callers, so
 * several API replicas booting at once do not race on the same migration.
 */
export async function runMigrations(handle: DbHandle): Promise<void> {
  const lockClient = await handle.pool.connect();
  try {
    await lockClient.query('select pg_advisory_lock($1)', [MIGRATION_LOCK_KEY]);
    // Same connection as the lock, so a pool of size 1 cannot deadlock.
    await migrate(drizzle(lockClient), { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    await lockClient
      .query('select pg_advisory_unlock($1)', [MIGRATION_LOCK_KEY])
      .catch(() => undefined);
    lockClient.release();
  }
}
